test("a reply from an earlier revision of the same epoch is dropped; a new epoch always applies", () => {
  const applied = { epoch: "e1", revision: 10 };
  assert.equal(app.isNewer(applied, { epoch: "e1", revision: 9 }), false);
  assert.equal(app.isNewer(applied, { epoch: "e1", revision: 10 }), true);
  assert.equal(app.isNewer(applied, { epoch: "e1", revision: 11 }), true);
  assert.equal(app.isNewer(applied, { epoch: "e2", revision: 0 }), true);
  assert.equal(app.isNewer(null, { epoch: "e1", revision: 0 }), true);
  assert.equal(app.isNewer(applied, null), false);
  assert.equal(app.sameStamp(applied, { epoch: "e1", revision: 10 }), true);
});

