/// The diff pass over three hundred sessions, timed and printed (run
/// with `--nocapture`); the spec's budget is 1 ms of frame time per
/// pass.
#[test]
fn the_fingerprint_pass_over_three_hundred_sessions_is_measured() {
    let mut port = port();
    let (_, project, _) = seed(&mut port, "ticket");
    for n in 1..300 {
        port.app.dispatch(AppAction::Control {
            op: format!("se{n}"),
            action: switchboard::core::ControlAction::try_from(Body::SessionNew {
                project: project.clone(),
                name: format!("s{n}"),
                session_kind: SessionKind::Shell,
                cwd: PathBuf::from("/tmp"),
                launch: Launch::Shell,
                prompt: None,
                notes: "n".repeat(500),
                env: std::collections::BTreeMap::new(),
                env_sets: Vec::new(),
                replaces: None,
            })
            .unwrap(),
        });
    }
    assert_eq!(port.app.core().workspaces()[0].sessions.len(), 300);
    let now = std::time::SystemTime::now();
    let t0 = std::time::Instant::now();
    let runs = 20;
    let mut fp = None;
    for _ in 0..runs {
        fp = Some(switchboard::core::revision::Fingerprints::of(
            port.app.core(),
            now,
        ));
    }
    let per_pass = t0.elapsed() / runs;
    let fp = fp.unwrap();
    let t1 = std::time::Instant::now();
    let changes = fp.changes(&fp);
    let compare = t1.elapsed();
    assert!(changes.is_empty());
    println!(
        "fingerprint pass over {} resources: {per_pass:?}; compare: {compare:?}",
        fp.len()
    );
}

/// Put `session`'s pane on the fake host, running, showing `text`.
fn pane_running(port: &mut Port, session: &str, text: &str) -> RecordId {
    let record = RecordId(uuid::Uuid::parse_str(session).unwrap());
    let pane = HostId(record.host_name());
    {
        let mut state = port.host.state();
        state.statuses.retain(|s| s.id != pane);
        state.statuses.push(HostStatus {
            id: pane.clone(),
            liveness: HostLiveness::Running {
                pid: 7,
                command: "claude".into(),
            },
            cwd: None,
            last_activity: None,
            title: None,
        });
        state.snapshots.insert(pane, text.into());
    }
    port.app.poll_now();
    record
}

/// Serve until `check` holds or `secs` pass.
fn settle(port: &mut Port, secs: u64, check: impl Fn(&SwitchboardApp) -> bool) -> bool {
    let deadline = std::time::Instant::now() + Duration::from_secs(secs);
    loop {
        port.app.serve_pending();
        if check(&port.app) {
            return true;
        }
        if std::time::Instant::now() > deadline {
            return false;
        }
        std::thread::sleep(Duration::from_millis(5));
    }
}

/// A screen read by a paired device: the revision and the text.
fn screen(port: &mut Port, session: &str, token: &str, lines: Option<usize>) -> (u64, String) {
    let query = lines.map(|n| format!("?lines={n}")).unwrap_or_default();
    let (status, reply) = get(
        port,
        &format!("/api/v1/sessions/{session}/screen{query}"),
        Some(token),
    );
    assert_eq!(status, 200, "{reply}");
    (
        reply["revision"].as_u64().unwrap(),
        reply["body"]["text"].as_str().unwrap().to_owned(),
    )
}

/// A `watch` is answered `watching` and enters the key; the poll then
/// observes the pane and emits `changed` for the screen; two reads of
/// the same text carry one revision, however many lines each asks for,
/// and the poll says nothing while the pane holds still; a pane that
/// moves is a new revision, which the next read carries.
#[test]
fn a_watched_screen_moves_on_poll_and_an_unchanged_read_keeps_its_revision() {
    let mut port = port();
    let (_, _, session) = seed(&mut port, "");
    let record = pane_running(&mut port, &session, "one\ntwo\n");
    port.app.set_watch_poll(Duration::from_millis(50));
    let token = pair(&mut port, "ABCD2345", Scope::Read, "Vision Pro");
    let sub = subscribe(&mut port, &token);
    sub.send("watch", "screen", &session);
    let got = events(&mut port, &sub);
    let moved = resources(&got);
    assert_eq!(
        moved.first(),
        Some(&("watching".into(), "screen".into(), session.clone())),
        "{moved:?}"
    );
    assert!(
        moved.contains(&("changed".into(), "screen".into(), session.clone())),
        "{moved:?}"
    );
    assert_eq!(port.app.watched_keys(), vec![ContentKey::Screen(record)]);
    let first = port
        .app
        .content_revision(&ContentKey::Screen(record))
        .unwrap();
    assert_eq!(got.last().unwrap()["revision"], first);

    let (r1, text) = screen(&mut port, &session, &token, None);
    assert_eq!((r1, text.as_str()), (first, "one\ntwo"));
    let (r2, text) = screen(&mut port, &session, &token, Some(1));
    assert_eq!((r2, text.as_str()), (first, "two"));
    assert!(events(&mut port, &sub).is_empty(), "nothing moved");

    port.host
        .state()
        .snapshots
        .insert(HostId(record.host_name()), "one\ntwo\nthree\n".into());
    let got = events(&mut port, &sub);
    assert_eq!(
        resources(&got),
        vec![("changed".into(), "screen".into(), session.clone())]
    );
    let next = got[0]["revision"].as_u64().unwrap();
    assert!(next > first);
    let (r3, text) = screen(&mut port, &session, &token, None);
    assert_eq!((r3, text.as_str()), (next, "one\ntwo\nthree"));
}

/// A secret added to the project after the watch moves the screen
/// though the pane did not: the policy is in the version, and the next
/// read carries the value's name instead of the value.
#[test]
fn a_policy_change_moves_a_watched_screen_though_the_pane_did_not() {
    let mut port = port();
    let (_, project, session) = seed(&mut port, "");
    pane_running(&mut port, &session, "$ env\nAPI_TOKEN=tok-5e3cr3t\n");
    port.app.set_watch_poll(Duration::from_millis(50));
    let token = pair(&mut port, "ABCD2345", Scope::Read, "Vision Pro");
    let sub = subscribe(&mut port, &token);
    sub.send("watch", "screen", &session);
    let got = events(&mut port, &sub);
    assert_eq!(got.len(), 2, "{got:?}");
    let (first, text) = screen(&mut port, &session, &token, None);
    assert!(
        text.contains("tok-5e3cr3t"),
        "no secret declared yet: {text}"
    );

    let pid = switchboard::core::ProjectId(uuid::Uuid::parse_str(&project).unwrap());
    port.secrets.state().insert(
        switchboard::core::SecretScope::Project(pid).account("API_TOKEN"),
        "tok-5e3cr3t".into(),
    );
    port.app.dispatch(AppAction::SetProjectEnv(
        pid,
        switchboard::core::ProjectEnv {
            vars: vec![switchboard::core::EnvVar {
                name: "API_TOKEN".into(),
                value: String::new(),
                secret: true,
            }],
            ..Default::default()
        },
    ));
    let got = events(&mut port, &sub);
    let moved = resources(&got);
    assert!(
        moved.contains(&("changed".into(), "screen".into(), session.clone())),
        "{moved:?}"
    );
    let (next, text) = screen(&mut port, &session, &token, None);
    assert!(next > first);
    assert_eq!(text, "$ env\nAPI_TOKEN=<API_TOKEN>");
}

/// Past the cap the least recently read key goes, silently; a read of
/// an evicted key works and puts it back, at another's expense.
#[test]
fn the_watch_set_is_capped_and_a_read_of_an_evicted_key_puts_it_back() {
    let mut port = port();
    let (_, project, _) = seed(&mut port, "");
    let token = pair(&mut port, "ABCD2345", Scope::Read, "Pad");
    let mut sessions = Vec::new();
    for n in 0..(switchboard::content::WATCH_CAP + 2) {
        // An op id of its own each: a repeated id is replayed.
        let reply = control(
            &mut port,
            Request::new(
                format!("se{n}"),
                Body::SessionNew {
                    project: project.clone(),
                    name: format!("s{n}"),
                    session_kind: SessionKind::Claude,
                    cwd: PathBuf::from("/tmp"),
                    launch: Launch::Shell,
                    prompt: None,
                    notes: String::new(),
                    env: std::collections::BTreeMap::new(),
                    env_sets: Vec::new(),
                    replaces: None,
                },
            ),
        );
        let session = made_id(&reply, RecordKind::Session);
        let record = pane_running(&mut port, &session, &format!("pane {n}\n"));
        sessions.push((session, ContentKey::Screen(record)));
    }
    for (session, _) in &sessions {
        screen(&mut port, session, &token, Some(1));
    }
    let watched = port.app.watched_keys();
    assert_eq!(watched.len(), switchboard::content::WATCH_CAP);
    assert!(!watched.contains(&sessions[0].1), "the first read went");
    assert!(!watched.contains(&sessions[1].1), "and the second");
    assert!(watched.contains(&sessions[2].1));

    let (_, text) = screen(&mut port, &sessions[0].0, &token, Some(1));
    assert_eq!(text, "pane 0");
    let watched = port.app.watched_keys();
    assert_eq!(watched.len(), switchboard::content::WATCH_CAP);
    assert!(watched.contains(&sessions[0].1), "back in");
    assert!(!watched.contains(&sessions[2].1), "the oldest went for it");
}

/// A key stays while any subscriber holds it: one device's `unwatch`
/// leaves the other's watch, a closed socket drops its watches, and a
/// revocation drops the device's at once. A watch of a pane that is
/// not running is answered `watching` too; it is read when it runs.
#[test]
fn unwatch_a_closed_socket_and_a_revocation_each_drop_their_watches() {
    let mut port = port();
    let (_, _, session) = seed(&mut port, "");
    let record = RecordId(uuid::Uuid::parse_str(&session).unwrap());
    let key = ContentKey::Screen(record);
    let token = pair(&mut port, "ABCD2345", Scope::Read, "Pad");
    let a = subscribe(&mut port, &token);
    let b = subscribe(&mut port, &token);
    a.send("watch", "screen", &session);
    b.send("watch", "screen", &session);
    assert_eq!(resources(&events(&mut port, &a)).len(), 1, "watching");
    assert_eq!(resources(&events(&mut port, &b)).len(), 1, "watching");
    assert_eq!(port.app.watched_keys(), vec![key.clone()]);

    a.send("unwatch", "screen", &session);
    assert!(events(&mut port, &a).is_empty());
    assert_eq!(
        port.app.watched_keys(),
        vec![key.clone()],
        "b still holds it"
    );

    b.close();
    assert!(
        settle(&mut port, 5, |app| app.watched_keys().is_empty()),
        "b's close dropped the watch"
    );
    assert_eq!(port.app.subscriber_count(), 1);

    a.send("watch", "screen", &session);
    assert!(settle(&mut port, 5, |app| !app.watched_keys().is_empty()));
    let device = port.app.core().devices()[0].id;
    port.app.dispatch(AppAction::RevokeDevice(device));
    assert!(
        port.app.watched_keys().is_empty(),
        "revoked with its watches"
    );
    assert_eq!(port.app.subscriber_count(), 0);
}

/// Strangers that connect and say nothing fill the unauthenticated
/// pool and no more: the fifth is closed at once, a paired subscriber
/// keeps receiving meanwhile, and the slots are free once they hang up.
#[test]
fn stalled_strangers_fill_their_own_pool_and_never_a_paired_clients() {
    let mut port = port();
    let token = pair(&mut port, "ABCD2345", Scope::Read, "Pad");
    let sub = subscribe(&mut port, &token);
    let strangers: Vec<TcpStream> = (0..MAX_UNAUTHENTICATED)
        .map(|_| TcpStream::connect(port.addr).expect("connect"))
        .collect();
    // The listener has handed each to a thread before it accepts more.
    std::thread::sleep(Duration::from_millis(100));
    let mut fifth = TcpStream::connect(port.addr).expect("connect");
    fifth
        .set_read_timeout(Some(Duration::from_secs(5)))
        .unwrap();
    let mut buf = [0u8; 1];
    let closed = matches!(fifth.read(&mut buf), Ok(0) | Err(_));
    assert!(closed, "the fifth stranger was closed at once");
    // A page load is a stranger too: the pool that is full refuses it.
    assert!(
        exchange(port.addr, &port.client, "GET", "/", &[], "").is_err(),
        "a page load past a full pool is closed at accept"
    );

    let (_, _, session) = seed(&mut port, "");
    let moved = resources(&events(&mut port, &sub));
    assert!(
        moved.contains(&("changed".into(), "session".into(), session.clone())),
        "the paired subscriber kept receiving: {moved:?}"
    );

    drop(strangers);
    std::thread::sleep(Duration::from_millis(100));
    let (status, _) = get(&mut port, "/api/v1/waiting", Some(&token));
    assert_eq!(status, 200, "the slots are free again");
}

// --- the web page

/// Open the window and pair as a browser does: the token comes back as a
/// cookie named for the host, and the body carries none. Returns the
/// device's id, the cookie's name and its token.
fn pair_cookie(port: &mut Port, code: &str, scope: Scope, name: &str) -> (String, String, String) {
    port.app.dispatch(AppAction::OpenPairing {
        code: code.into(),
        scope,
    });
    let identity = port.remote.state().identity.clone().unwrap();
    let body = serde_json::json!({
        "code": code,
        "spki_sha256": identity.spki_sha256,
        "device_name": name,
        "transport": "cookie",
    });
    let (head, reply) = call_with(port, "POST", "/api/v1/pair", &[], &body.to_string());
    assert_eq!(head.status, 200, "{reply}");
    let cookie = remote::cookie_name(identity.server_id);
    let set = head.header("set-cookie").expect("a Set-Cookie");
    let token = set
        .split(';')
        .next()
        .and_then(|pair| pair.strip_prefix(&format!("{cookie}=")))
        .expect("the cookie is named for this host")
        .to_owned();
    let device = reply["body"]["device_id"].as_str().unwrap().to_owned();
    (device, cookie, token)
}

/// The Content-Security-Policy the page's replies carry, exactly.
const PAGE_CSP: &str = "default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; img-src 'self' data:; base-uri 'none'; form-action 'none'; frame-ancestors 'none'";

/// The three page files answer to anyone, with their type and the policy;
/// anything else outside the API is the frame's JSON refusal.
#[test]
fn the_page_files_answer_before_pairing_with_their_policy() {
    let mut port = port();
    let pages = [
        (
            "/",
            include_str!("../web/index.html"),
            "text/html; charset=utf-8",
        ),
        (
            "/app.js",
            include_str!("../web/app.js"),
            "text/javascript; charset=utf-8",
        ),
        (
            "/app.css",
            include_str!("../web/app.css"),
            "text/css; charset=utf-8",
        ),
    ];
    for (path, body, content_type) in pages {
        let head = exchange(port.addr, &port.client, "GET", path, &[], "").expect("page");
        assert_eq!(head.status, 200, "{path}");
        assert_eq!(head.header("content-type"), Some(content_type), "{path}");
        assert_eq!(
            head.header("content-security-policy"),
            Some(PAGE_CSP),
            "{path}"
        );
        assert_eq!(head.header("cache-control"), Some("no-store"), "{path}");
        assert_eq!(
            head.header("x-content-type-options"),
            Some("nosniff"),
            "{path}"
        );
        assert_eq!(
            head.header("referrer-policy"),
            Some("no-referrer"),
            "{path}"
        );
        assert_eq!(head.header("connection"), Some("close"), "{path}");
        assert_eq!(head.body, body, "{path}");
    }
    // A query is ignored and never echoed.
    let head = exchange(port.addr, &port.client, "GET", "/?code=ABCD2345", &[], "").unwrap();
    assert_eq!(head.body, include_str!("../web/index.html"));

    for (method, path) in [("GET", "/favicon.ico"), ("GET", "/api"), ("POST", "/")] {
        let (status, reply) = call(&mut port, method, path, None, "");
        assert_eq!(
            (status, code(&reply)),
            (404, "not_found"),
            "{method} {path}: {reply}"
        );
    }
}

/// The page names only what the host serves, and its markup and script
/// stay inside the policy: no inline script, style or handler, no markup
/// written from a string. Every API path the script names answers for a
/// paired device, something other than `not_found`.
#[test]
fn the_page_names_only_what_the_host_serves_and_keeps_its_markup_plain() {
    let mut port = port();
    let html = include_str!("../web/index.html");
    let script = include_str!("../web/app.js");
    for attr in ["src=\"", "href=\""] {
        for (at, _) in html.match_indices(attr) {
            let value = &html[at + attr.len()..];
            let value = &value[..value.find('"').unwrap()];
            assert!(
                ["/", "/app.js", "/app.css"].contains(&value) || value.starts_with("data:"),
                "{value} is not served"
            );
        }
    }
    for (at, _) in html.match_indices("<script") {
        let tag = &html[at..at + html[at..].find('>').unwrap()];
        assert!(tag.contains("src="), "an inline script: {tag}");
    }
    assert!(!html.contains("style="), "no inline style");
    assert!(
        !html
            .split_whitespace()
            .any(|w| w.starts_with("on") && w.contains('=')),
        "no inline handler"
    );
    for banned in [
        "innerHTML",
        "outerHTML",
        "eval(",
        "document.write",
        "insertAdjacentHTML",
    ] {
        assert!(!script.contains(banned), "the script uses {banned}");
    }

    let (_, project, session) = seed(&mut port, "");
    let token = pair(&mut port, "ABCD2345", Scope::Control, "Vision Pro");
    let mut checked = 0;
    for (at, _) in script.match_indices("\"/api/v1/") {
        let rest = &script[at + 1..];
        let path = &rest[..rest.find('"').unwrap()];
        let path = if path.contains("projects/{id}") {
            path.replace("{id}", &project)
        } else {
            path.replace("{id}", &session)
        };
        let (method, bearer) = match path.as_str() {
            "/api/v1/pair" => ("POST", None),
            p if p.ends_with("/send") => ("POST", Some(token.as_str())),
            _ => ("GET", Some(token.as_str())),
        };
        let (status, reply) = call(&mut port, method, &path, bearer, "{}");
        assert_ne!(
            code(&reply),
            "not_found",
            "{method} {path}: {status} {reply}"
        );
        checked += 1;
    }
    assert!(checked >= 10, "the script names its routes: {checked}");
}

/// A browser pairs as the page does: the cookie is `HttpOnly`, `Secure`,
/// `SameSite=Strict`, `__Host-` and named for the host, and the body holds
/// no token. The cookie alone reads `/me`. A native pair is unchanged.
#[test]
fn a_browser_pairs_with_a_cookie_and_no_token_in_the_body() {
    let mut port = port();
    let identity = port.remote.state().identity.clone().unwrap();
    port.app.dispatch(AppAction::OpenPairing {
        code: "ABCD2345".into(),
        scope: Scope::Read,
    });
    let body = serde_json::json!({
        "code": "ABCD2345",
        "spki_sha256": identity.spki_sha256,
        "device_name": "Safari on iPhone",
        "transport": "cookie",
    });
    let (head, reply) = call_with(&mut port, "POST", "/api/v1/pair", &[], &body.to_string());
    assert_eq!(head.status, 200, "{reply}");
    let name = format!("__Host-sb-{}", identity.server_id);
    let set = head.header("set-cookie").expect("a Set-Cookie");
    let (pair, attrs) = set.split_once("; ").unwrap();
    assert!(pair.starts_with(&format!("{name}=")), "{set}");
    for attr in [
        "Max-Age=34560000",
        "Path=/",
        "Secure",
        "HttpOnly",
        "SameSite=Strict",
    ] {
        assert!(attrs.split("; ").any(|a| a == attr), "{attr} in {set}");
    }
    assert!(!set.contains("Domain"), "{set}");
    assert!(reply["body"]["token"].is_null(), "no token in the body");
    assert_eq!(reply["body"]["server_id"], identity.server_id.to_string());

    let cookie = format!("{}={}", name, &pair[name.len() + 1..]);
    let (head, me) = call_with(&mut port, "GET", "/api/v1/me", &[("Cookie", &cookie)], "");
    assert_eq!(head.status, 200, "{me}");
    assert_eq!(me["body"]["name"], "Safari on iPhone");
    assert_eq!(me["body"]["scope"], "read");
    assert_eq!(me["body"]["server_name"], identity.server_name);

    // The window closed with that pairing, so a native pair opens its own.
    port.app.dispatch(AppAction::OpenPairing {
        code: "BBBB2345".into(),
        scope: Scope::Read,
    });
    let native_body = serde_json::json!({
        "code": "BBBB2345",
        "spki_sha256": identity.spki_sha256,
        "device_name": "Vision Pro",
    });
    let (head, native) = call_with(
        &mut port,
        "POST",
        "/api/v1/pair",
        &[],
        &native_body.to_string(),
    );
    assert_eq!(head.status, 200, "{native}");
    assert!(
        head.header("set-cookie").is_none(),
        "a native pair gets no cookie"
    );
    assert!(
        native["body"]["token"].is_string(),
        "its token is in the body"
    );
}

/// Two instances on one address: each host's cookie is its own name, a
/// host reads only its own, and a cookie under the fixed name reads nothing.
#[test]
fn two_hosts_on_one_address_never_read_each_others_cookie() {
    let mut a = port();
    let mut b = port();
    let (device_a, name_a, token_a) = pair_cookie(&mut a, "ABCD2345", Scope::Read, "Pad");
    let (_, name_b, token_b) = pair_cookie(&mut b, "ABCD2345", Scope::Read, "Pad");
    assert_ne!(name_a, name_b, "each host names its cookie for its own id");

    let only_b = format!("{name_b}={token_b}");
    let (head, _) = call_with(&mut a, "GET", "/api/v1/me", &[("Cookie", &only_b)], "");
    assert_eq!(head.status, 401, "another host's cookie is not this host's");

    let both = format!("{only_b}; {name_a}={token_a}");
    let (head, me) = call_with(&mut a, "GET", "/api/v1/me", &[("Cookie", &both)], "");
    assert_eq!(head.status, 200, "{me}");
    assert_eq!(me["body"]["device_id"], device_a, "a's own device");

    let fixed = format!("__Host-sb={token_a}");
    let (head, _) = call_with(&mut a, "GET", "/api/v1/me", &[("Cookie", &fixed)], "");
    assert_eq!(head.status, 401, "the fixed name authenticates nothing");
}

/// A cookie is a credential the browser sends on its own, so a write from
/// it must come from this host's own origin; a bearer, a read, and a write
/// from the right origin are not refused for the origin.
#[test]
fn a_write_by_cookie_must_come_from_this_hosts_own_origin() {
    let mut port = port();
    let (_, _, session) = seed(&mut port, "");
    let (_, name, token) = pair_cookie(&mut port, "ABCD2345", Scope::Control, "Pad");
    let cookie = format!("{name}={token}");
    let path = format!("/api/v1/sessions/{session}/send");
    let body = r#"{"op":"o1","text":"hi"}"#;

    let (head, reply) = call_with(&mut port, "POST", &path, &[("Cookie", &cookie)], body);
    assert_eq!((head.status, code(&reply)), (403, "origin"), "{reply}");
    let (head, reply) = call_with(
        &mut port,
        "POST",
        &path,
        &[("Cookie", &cookie), ("Origin", "https://evil.example")],
        body,
    );
    assert_eq!((head.status, code(&reply)), (403, "origin"), "{reply}");
    let (head, reply) = call_with(
        &mut port,
        "POST",
        &path,
        &[("Cookie", &cookie), ("Origin", "https://localhost")],
        body,
    );
    assert_ne!(code(&reply), "origin", "{reply}");
    assert_ne!(head.status, 403, "{reply}");

    let bearer = pair(&mut port, "BBBB2345", Scope::Control, "Vision Pro");
    let (_, reply) = call(&mut port, "POST", &path, Some(&bearer), body);
    assert_ne!(code(&reply), "origin", "a bearer is exempt: {reply}");
    let (head, _) = call_with(
        &mut port,
        "GET",
        "/api/v1/waiting",
        &[("Cookie", &cookie)],
        "",
    );
    assert_eq!(head.status, 200, "a read by cookie needs no origin");
}

/// The same rule holds for the events socket's upgrade: a cookie upgrade
/// from another origin is refused, and from this host's own origin it is
/// accepted (101).
#[test]
fn a_cookie_upgrade_must_come_from_this_hosts_own_origin() {
    let mut port = port();
    let (_, name, token) = pair_cookie(&mut port, "ABCD2345", Scope::Read, "Pad");
    let cookie = format!("{name}={token}");
    let upgrade = |origin: &'static str| {
        vec![
            ("Upgrade", "websocket"),
            ("Connection", "Upgrade"),
            ("Sec-WebSocket-Version", "13"),
            ("Sec-WebSocket-Key", "dGhlIHNhbXBsZSBub25jZQ=="),
            ("Cookie", cookie.as_str()),
            ("Origin", origin),
        ]
    };
    let head = head_with(
        &mut port,
        "GET",
        "/api/v1/events",
        &upgrade("https://evil.example"),
        "",
    );
    assert_eq!(head.status, 403, "{}", head.body);
    assert!(head.body.contains("\"origin\""), "{}", head.body);
    let head = head_with(
        &mut port,
        "GET",
        "/api/v1/events",
        &upgrade("https://localhost"),
        "",
    );
    assert_eq!(head.status, 101, "{}", head.body);
}

/// `/me` says the scope the device has now, and follows a change of it.
